/**
 * 团队视图只读投影：事件流 + 注册表 + 黑板分片 → 视图模型（issue #68）。
 *
 * 归约与渲染分离（issue 验收第 4 条）：本模块是平台无关纯函数，输入为已
 * 就绪的数据切片（调用方负责读文件与尾部截断），输出为画布可直接渲染的
 * 视图模型——视图正确性 = 归约正确性，全部语义在此单测覆盖。
 *
 * 只读保证：零写路径、零 IO；payload 不出投影面（浏览器侧纯文本渲染，
 * 最小暴露原则）。
 *
 * 着色语义（对抗性评审修订：liveness 优先于活动态——黑板可能是死者遗留的
 * 陈旧数据，注册表终局态一票否决）：
 *   lost（dead 成员） > 黑板 running/blocked/done > idle（spawned/stopped/
 *   无分片等静默态）。stopped 不并入运行类着色（明确不是排队）；lastSeen
 *   陈旧横切不做——协议无心跳间隔定义，任意阈值都会把长任务静默期误标。
 */
import type { EventRecord, MemberRecord, TeamRegistry } from "../kernel/types.js";
import type { Shard } from "../collab/blackboard.js";

/** 节点着色语义（运行中/阻塞/已完成/静默/失联）+ 图例文案。 */
export type NodeTone = "running" | "blocked" | "done" | "idle" | "lost";

/** 单个房间归约输入：调用方已读取并截断的事件尾部窗口 + 黑板分片。 */
export interface OverviewRoomInput {
  room: string;
  /** 事件尾部窗口（已按 seq 升序；由调用方 tail 截断）。 */
  events: readonly EventRecord[];
  /** 该房间黑板分片快照。 */
  shards: readonly Shard[];
}

/** 归约输入整体。 */
export interface OverviewInput {
  registry: TeamRegistry;
  rooms: readonly OverviewRoomInput[];
}

/** 成员节点视图（L1 树节点 / L2 抽屉详情共用）。 */
export interface MemberNodeView {
  member: string;
  tier: number;
  /** 直接父成员名（根成员为 null）；父未注册时挂 null（前端归 root 层）。 */
  parent: string | null;
  /** 持久身份锚点：执行成员 = durable subagent id；tier0 主控 = 宿主主会话 id（#79）。 */
  durableId: string | null;
  /** agents.json 注册态原文（徽标辅助图标用）；未注册成员无此字段语义 → null。 */
  registryStatus: MemberRecord["status"] | null;
  tone: NodeTone;
  currentActivity: string | null;
  lastSeen: number | null;
}

/** 房间视图（L1 汇总徽标 / L2 抽屉事件摘要共用）。payload 不出投影面。 */
export interface RoomView {
  room: string;
  counts: Record<NodeTone, number>;
  recentEvents: Array<Pick<EventRecord, "seq" | "ts" | "actor" | "type">>;
}

/** 团队总览视图模型。 */
export interface TeamOverview {
  isTeam: boolean;
  /**
   * tier0 主控是否已在册（#79 L3 单一确定信号）：false = 实例已初始化但
   * 主控记录缺失（旧实例兼容态 / 未完成启动握手）→ 前端渲染静态黄条。
   * 注意信号单向：只识别「未登记」，不判定「登记了但未跑对账」。
   */
  masterRegistered: boolean;
  /** 全体注册成员扁平表（前端按 parent 组装 root 主房间的树）。 */
  members: MemberNodeView[];
  rooms: RoomView[];
}

/**
 * 从黑板分片推导活动着色（仅三分支：blocked/running/done，其余一律 idle）。
 * 注意：结果会被 reduceOverview 的 liveness 一票否决覆盖（dead → lost）。
 */
export function toneOfShard(shard: Shard | undefined): Exclude<NodeTone, "lost"> {
  if (shard === undefined) return "idle";
  if (shard.status === "blocked") return "blocked";
  if (shard.status === "running") return "running";
  if (shard.status === "done") return "done";
  return "idle";
}

/** 从分片 ext 提取 current_activity（非空字符串才认可；机械取值零生成）。 */
function activityFromExt(ext: unknown): string | null {
  if (ext !== null && typeof ext === "object") {
    const v = (ext as { current_activity?: unknown }).current_activity;
    if (typeof v === "string" && v.length > 0) return v;
  }
  return null;
}

/**
 * 成员当前活动摘要：优先黑板 ext.current_activity，其次该成员在事件尾部
 * 窗口内最近一条事件的 type（机械取 type 原文，不做语言生成），两者皆无则
 * null。
 */
export function currentActivityOf(
  member: string,
  shard: Shard | undefined,
  events: readonly EventRecord[],
): string | null {
  const fromExt = shard === undefined ? null : activityFromExt(shard.ext);
  if (fromExt !== null) return fromExt;
  for (let i = events.length - 1; i >= 0; i--) {
    const e = events[i]!;
    if (e.actor === member) return e.type;
  }
  return null;
}

/** 单房间计数与事件摘要投影。events 为空/缺文件时返回空态（断网降级同理）。 */
export function reduceRoom(input: OverviewRoomInput): RoomView {
  const counts: Record<NodeTone, number> = { running: 0, blocked: 0, done: 0, idle: 0, lost: 0 };
  for (const shard of input.shards) counts[toneOfShard(shard)] += 1;
  return {
    room: input.room,
    counts,
    recentEvents: input.events.map((e) => ({ seq: e.seq, ts: e.ts, actor: e.actor, type: e.type })),
  };
}

/**
 * 总览归约：注册表成员逐个投影（含未在任何房间写过黑板的成员——灰态可见，
 * 保证 L1 一屏可见全团队），房间逐个投影。registry.members 为空即视为
 * 非团队实例（isTeam=false，路由层据此短路）。
 *
 * 着色优先级：registryStatus=dead → lost（一票否决）；其余取分片活动态
 * （缺失 → idle）。多房间同角色分片并存时取字典序首个房间的分片，确定性可测。
 */
export function reduceOverview(input: OverviewInput): TeamOverview {
  const memberNames = Object.keys(input.registry.members).sort();
  const shardIndex = new Map<string, Shard>();
  const eventsByActor = new Map<string, readonly EventRecord[]>();
  for (const room of input.rooms) {
    for (const shard of room.shards) {
      if (!shardIndex.has(shard.role)) shardIndex.set(shard.role, shard);
    }
    for (const e of room.events) {
      const bucket = eventsByActor.get(e.actor);
      eventsByActor.set(e.actor, bucket === undefined ? [e] : [...bucket, e]);
    }
  }
  const members = memberNames.map((name) => {
    const record: MemberRecord = input.registry.members[name]!;
    const shard = shardIndex.get(name);
    return {
      member: name,
      tier: record.tier,
      parent: record.parent ?? null,
      durableId: record.durableId,
      registryStatus: record.status,
      tone: record.status === "dead" ? ("lost" as const) : toneOfShard(shard),
      currentActivity: currentActivityOf(name, shard, eventsByActor.get(name) ?? []),
      lastSeen: Number.isFinite(record.lastSeen) ? record.lastSeen : null,
    };
  });
  return {
    isTeam: memberNames.length > 0,
    masterRegistered: memberNames.some((n) => input.registry.members[n]!.tier === 0),
    members,
    rooms: input.rooms.map(reduceRoom),
  };
}

tests/plugin/dispatch.test.ts.source:
/**
 * team_dispatch 复合派发原语单测（ADR 0015，#67）。
 * 覆盖：正常三步链路（含 role_inline / provider / model 透传）、
 * 半事务失败（步骤留痕 + 副作用边界）、前置校验、role_inline 白名单、幂等重入。
 */
import { describe, expect, it, beforeEach } from "vitest";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createHandlers, type Handlers } from "../../src/plugin/handlers.js";
import { EventLog } from "../../src/runtime/kernel/event-log.js";
import { Registry } from "../../src/runtime/kernel/registry.js";
import { layout } from "../../src/runtime/kernel/paths.js";
import { readUnread } from "../../src/runtime/collab/mailbox.js";

let home: string;
let handlers: Handlers;
const SESSION = "session-dispatch-1";

beforeEach(() => {
  home = mkdtempSync(join(tmpdir(), "xzg-dispatch-"));
  handlers = createHandlers(home, SESSION);
});

async function readEvents(): Promise<Array<{ type: string; actor: string }>> {
  const log = new EventLog(join(layout(home).roomsDir, "root", "events.jsonl"));
  await log.init();
  const { events } = await log.read();
  return events.map((e) => ({ type: e.type, actor: e.actor }));
}

async function createTask(title = "实现 X"): Promise<string> {
  const created = (await handlers.taskCreate({ title, room: "root" })) as {
    ok: true;
    task_id: string;
  };
  return created.task_id;
}

describe("team_dispatch 正常链路", () => {
  it("spawn→assign→send 三步全成，注册表/账本/信箱/事件流逐项核对", async () => {
    await handlers.init({});
    const taskId = await createTask();

    const result = (await handlers.dispatch({
      member: "coder",
      durable_id: "dur-coder",
      role: "coder",
      tier: 1,
      task_id: taskId,
      provider: "deepseek",
      model: "strong-model",
      role_inline: {
        briefing: "专注构建门禁",
        dod: ["build 绿"],
        max_hops: 3,
        as_judge: false,
      },
    })) as {
      ok: boolean;
      member: string;
      durable_id: string;
      task_id: string;
      envelope_id: string;
      steps: string[];
    };

    expect(result.ok).toBe(true);
    expect(result.member).toBe("coder");
    expect(result.durable_id).toBe("dur-coder");
    expect(result.task_id).toBe(taskId);
    expect(result.steps).toEqual(["spawn", "assign", "send"]);

    // 注册表：成员已登记。
    const member = await new Registry(home).getMember("coder");
    expect(member).toMatchObject({ member: "coder", durableId: "dur-coder", tier: 1, status: "spawned" });

    // 账本：任务已指派。
    const ledgerView = (await handlers.taskList({})) as {
      tasks: Array<{ id: string; assignee?: string }>;
    };
    expect(ledgerView.tasks.find((t) => t.id === taskId)?.assignee).toBe("coder");

    // 信箱：派单信封携带任务与 inline 定义、模型档位。
    const unread = await readUnread(home, "coder");
    expect(unread).toHaveLength(1);
    expect(unread[0]).toMatchObject({
      from: "root",
      to: "coder",
      type: "task-assign",
      body: {
        task_id: taskId,
        title: "实现 X",
        room: "root",
        dod: [],
        role_inline: { briefing: "专注构建门禁", dod: ["build 绿"], max_hops: 3, as_judge: false },
        provider: "deepseek",
        model: "strong-model",
      },
    });
    expect(unread[0]?.envelope_id ?? unread[0]!.id).toBe(result.envelope_id);

    // 事件流：三步各留一笔。
    expect(await readEvents()).toMatchObject([
      { type: "team/init", actor: "system" },
      { type: "task/create", actor: "system" },
      { type: "team/spawn", actor: "system" },
      { type: "task/update", actor: "coder" },
      { type: "mailbox/deliver", actor: "root" },
    ]);
  });

  it("幂等重入：同参数重跑成功，upsert 幂等、派单为新信封（at-least-once）", async () => {
    await handlers.init({});
    const taskId = await createTask();
    const first = await handlers.dispatch({
      member: "qa",
      durable_id: "dur-qa",
      role: "qa",
      tier: 1,
      task_id: taskId,
    });
    expect(first).toMatchObject({ ok: true, steps: ["spawn", "assign", "send"] });

    // 重入：upsert 幂等、assignee 不变、派单为新信封（at-least-once 语义）。
    const second = (await handlers.dispatch({
      member: "qa",
      durable_id: "dur-qa",
      role: "qa",
      tier: 1,
      task_id: taskId,
    })) as { ok: boolean; envelope_id: string };
    expect(second.ok).toBe(true);
    expect(second.envelope_id).not.toBe((first as { envelope_id: string }).envelope_id);
    const unread = await readUnread(home, "qa");
    expect(unread).toHaveLength(2);
  });
});

describe("team_dispatch 半事务语义", () => {
  it("step2 rev 冲突即停：已完成 spawn 随错误留痕，assignee 未变、无信封", async () => {
    await handlers.init({});
    const taskId = await createTask();
    // 推高账本 rev，使 dispatch 的 expect_rev 过期。
    await handlers.taskUpdate({ task_id: taskId, rounds: 1 });

    await expect(
      handlers.dispatch({
        member: "coder",
        durable_id: "dur-coder",
        role: "coder",
        tier: 1,
        task_id: taskId,
        expect_rev: 1,
      }),
    ).rejects.toMatchObject({ code: "rev-conflict" });

    // step1 的副作用留存（注册表 + 事件），step2/3 未发生。
    const member = await new Registry(home).getMember("coder");
    expect(member?.member).toBe("coder");
    const events = await readEvents();
    expect(events.filter((e) => e.type === "team/spawn")).toHaveLength(1);
    expect(events.some((e) => e.type === "mailbox/deliver")).toBe(false);
    expect(await readUnread(home, "coder")).toHaveLength(0);

    const ledgerView = (await handlers.taskList({})) as {
      tasks: Array<{ id: string; assignee?: string }>;
    };
    expect(ledgerView.tasks.find((t) => t.id === taskId)?.assignee).toBeUndefined();
  });
});

describe("team_dispatch 前置校验（无副作用）", () => {
  it("任务不存在 → task-not-found，不产生任何落账副作用", async () => {
    await handlers.init({});
    await expect(
      handlers.dispatch({
